bool resolve_bool_expr(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    if (!expr || !set_rtrn) {
        return false;
    }

    switch (expr->type) {
        case EXPR_CONSTANT: {
            if (expr->u.constant.type == TYPE_BOOLEAN) {
                *set_rtrn = expr->u.constant.value.b;
                return true;
            }
            break;
        }

        case EXPR_IDENTIFIER: {
            if (strcmp(expr->u.identifier.name, "true") == 0) {
                *set_rtrn = true;
                return true;
            } else if (strcmp(expr->u.identifier.name, "false") == 0) {
                *set_rtrn = false;
                return true;
            }
            break;
        }

        case EXPR_FIELD_REF: {
            // Handle field reference resolution if required
            xkb_log(ctx, XKB_LOG_LEVEL_WARN, "Field references are not supported in boolean resolution.");
            break;
        }

        case EXPR_UNARY_OP: {
            if (expr->u.unary_op.op == OP_LOGICAL_NOT) {
                bool operand = false;
                bool success = resolve_bool_expr(ctx, expr->u.unary_op.arg, &operand);
                if (success) {
                    *set_rtrn = !operand;
                    return true;
                }
            }
            break;
        }

        default:
            xkb_log(ctx, XKB_LOG_LEVEL_WARN, "Unsupported boolean expression type.");
            break;
    }

    return false;
}

bool resolve_boolean_expression(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    switch (expr->type) {
        case EXPR_BOOLEAN_CONSTANT: {
            if (expr->value.bool_val != NULL) {
                *set_rtrn = *expr->value.bool_val;
                return true;
            }
            break;
        }

        case EXPR_IDENTIFIER: {
            if (expr->value.identifier != NULL) {
                if (strcmp(expr->value.identifier, "true") == 0) {
                    *set_rtrn = true;
                    return true;
                } else if (strcmp(expr->value.identifier, "false") == 0) {
                    *set_rtrn = false;
                    return true;
                } else {
                    xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unknown boolean identifier: %s", expr->value.identifier);
                    return false;
                }
            }
            break;
        }

        case EXPR_UNARY_OP: {
            if (expr->value.unary_op != NULL && expr->value.unary_op->type == UNARY_LOGICAL_NOT) {
                if (resolve_boolean_expression(ctx, expr->value.unary_op->operand, set_rtrn)) {
                    *set_rtrn = !(*set_rtrn);
                    return true;
                }
            }
            break;
        }

        default: {
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unsupported boolean expression type");
            return false;
        }
    }

    xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Failed to resolve boolean expression");
    return false;
}

bool resolve_bool_expr(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    switch (expr->type) {
        case EXPR_CONSTANT:
            if (expr->u.constant.type == TYPE_BOOLEAN) {
                *set_rtrn = expr->u.constant.value.b;
                return true;
            }
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Constant is not a boolean value.");
            return false;

        case EXPR_IDENTIFIER:
            if (!strcmp(expr->u.identifier.name, "true")) {
                *set_rtrn = true;
                return true;
            } else if (!strcmp(expr->u.identifier.name, "false")) {
                *set_rtrn = false;
                return true;
            }
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unknown identifier: %s.", expr->u.identifier.name);
            return false;

        case EXPR_FIELD_REF:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Field reference not supported in boolean resolution.");
            return false;

        case EXPR_OP_UNARY:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unary operations not supported in boolean resolution.");
            return false;

        default:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unsupported expression type.");
            return false;
    }
}

