bool resolve_bool_expression(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    if (expr == NULL || set_rtrn == NULL)
        return false;

    switch (expr->type) {
        case EXPR_BOOLEAN:
            if (expr->value.boolean == true || expr->value.boolean == false) {
                *set_rtrn = expr->value.boolean;
                return true;
            }
            break;

        case EXPR_IDENTIFIER: {
            if (strcmp(expr->value.identifier, "true") == 0) {
                *set_rtrn = true;
                return true;
            } else if (strcmp(expr->value.identifier, "false") == 0) {
                *set_rtrn = false;
                return true;
            } else {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unknown boolean identifier: %s\n", expr->value.identifier);
                return false;
            }
        }

        case EXPR_FIELD_REF:
        case EXPR_UNARY_OP:
        default:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unsupported boolean expression type: %d\n", expr->type);
            return false;
    }

    return false;
}
